@startuml
class Animal {
  +identifier : long
  +name : string
  +breed : string
}

class Owner {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Breed {
  +name : string
}

class Physician {
  +identifier : long
  +name : string
  +address : string
  +phone_number : string
}

class Appointment {
  +date_time : datetime
}

class Condition {
  +common_name : string
  +scientific_name : string
}

"0..1" -- "*" Animal : owns
"1" -- "*" Animal : belongs to
"1" -- "*" Appointment : is attended by
"1" -- "*" Appointment : is responsible for
"1" -- "*" Appointment : is attended by
"1" -- "*" Breed : has common conditions
"1" -- "*" Condition : is a common condition for
"1" -- "*" Condition : is a common condition for
@enduml

